create table if not exists gov_repo.ai_systems (system_id uuid primary key default uuid_generate_v4(),system_code varchar(20) not null,name varchar(255) not null,description text not null,intended_purpose text not null,risk_class gov_repo.ai_act_risk_class not null default 'minimal',status gov_repo.system_status not null default 'development',owner_user_id uuid not null references gov_repo.governance_users(user_id),business_domain varchar(100),eu_ai_db_registered boolean not null default false,eu_ai_db_ref varchar(100),conformity_assessment_id uuid references gov_repo.conformity_assessments(assessment_id),organisation_id uuid not null references gov_repo.organisations(organisation_id),ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint ai_systems_code_org_unique unique(system_code,organisation_id));
create index if not exists idx_ai_systems_org on gov_repo.ai_systems(organisation_id);
do $$ begin if not exists(select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='gov_repo' and c.relname='ai_systems' and t.tgname='trg_ai_systems_updated_at') then create trigger trg_ai_systems_updated_at before update on gov_repo.ai_systems for each row execute function gov_repo.set_updated_at(); end if; end $$;
do $$ begin if not exists(select 1 from information_schema.table_constraints where constraint_schema='gov_repo' and table_name='agents' and constraint_name='fk_agent_ai_system') then alter table gov_repo.agents add constraint fk_agent_ai_system foreign key(ai_system_id) references gov_repo.ai_systems(system_id); end if; end $$;
alter table gov_repo.ai_systems enable row level security;
do $$ begin if not exists(select 1 from pg_policies where schemaname='gov_repo' and tablename='ai_systems' and policyname='Service role full access ai_systems') then execute $pol$ create policy "Service role full access ai_systems" on gov_repo.ai_systems for all to service_role using(true) with check(true) $pol$; end if; end $$;
do $$ begin if not exists(select 1 from pg_policies where schemaname='gov_repo' and tablename='ai_systems' and policyname='Org-scoped ai_systems') then execute $pol$ create policy "Org-scoped ai_systems" on gov_repo.ai_systems for select to authenticated using(organisation_id=(select organisation_id from gov_repo.governance_users where email=auth.email() limit 1)) $pol$; end if; end $$;
alter table gov_repo.ai_systems add column if not exists lifecycle gov_repo.ai_system_lifecycle not null default 'development',add column if not exists version varchar(50) not null default '1.0.0',add column if not exists version_notes text,add column if not exists display_code varchar(10),add column if not exists annex_iii_sector gov_repo.annex_iii_sector not null default 'not_annex_iii',add column if not exists industry_sector varchar(100),add column if not exists geographic_scope varchar(100),add column if not exists deployment_env varchar(30) not null default 'development' check(deployment_env in ('development','staging','production')),add column if not exists deployment_regions text[] not null default '{}',add column if not exists deployment_type varchar(30) not null default 'on_premises' check(deployment_type in ('on_premises','private_cloud','hybrid','public_cloud')),add column if not exists is_cross_border boolean not null default false;
comment on column gov_repo.ai_systems.lifecycle is 'Full lifecycle stage per AI Act Art. 17 QMS. Complements stub status column. pre_market_review: conformity assessment submitted. conformity_assessed: passed; CE marking may be affixed (Art. 47). under_significant_modification: Art. 83 triggers new conformity assessment.';
comment on column gov_repo.ai_systems.annex_iii_sector is 'EU AI Act Annex III classification. If not not_annex_iii, system is presumptively high-risk (Art. 6(2)). Financial services credit scoring = essential_services_benefits. Biometric ID systems face additional restrictions under Art. 5 (prohibited uses).';
comment on column gov_repo.ai_systems.is_cross_border is 'TRUE if the AI system is used or affects persons in more than one EU Member State. Cross-border high-risk systems may require notification to multiple NCAs. Relevant for DORA Art. 28 cross-border ICT concentration risk.';
alter table gov_repo.ai_systems add column if not exists organisation_role gov_repo.provider_role not null default 'provider_and_deployer',add column if not exists provider_legal_name varchar(500),add column if not exists provider_address text,add column if not exists provider_country char(2),add column if not exists provider_contact_email varchar(255),add column if not exists eu_rep_name varchar(255),add column if not exists eu_rep_address text,add column if not exists eu_rep_country char(2) check(eu_rep_country is null or length(eu_rep_country)=2),add column if not exists eu_rep_contact_email varchar(255),add column if not exists deployer_legal_name varchar(500),add column if not exists deployer_address text,add column if not exists deployer_country char(2),add column if not exists technical_owner_id uuid references gov_repo.governance_users(user_id),add column if not exists ai_officer_id uuid references gov_repo.governance_users(user_id),add column if not exists dpo_id uuid references gov_repo.governance_users(user_id);
comment on column gov_repo.ai_systems.organisation_role is 'EU AI Act Art. 3 role of the owning organisation in this AI system. provider = built and places on market (Art. 16 obligations apply). deployer = uses system under own responsibility (Art. 26 obligations apply). Most internal bank AI systems are provider_and_deployer. Obligations differ: provider must ensure conformity; deployer must implement oversight.';
comment on column gov_repo.ai_systems.eu_rep_name is 'EU Authorised Representative per AI Act Art. 22. MANDATORY if the provider is established outside the EU. The representative acts on behalf of the provider for regulatory obligations. NULL = provider is EU-established (most common for domestic banks).';
comment on column gov_repo.ai_systems.ai_officer_id is 'AI Officer per EU AI Act Art. 3(8) — the natural person responsible for AI literacy, governance, and AI Act compliance within the organisation. Required for all deployers of high-risk AI systems under Art. 26(6).';
alter table gov_repo.ai_systems add column if not exists gpai_tier gov_repo.gpai_tier not null default 'not_gpai',add column if not exists gpai_model_ref varchar(255),add column if not exists gpai_training_flops numeric(30,0),add column if not exists annex_iii_exception_claimed boolean not null default false,add column if not exists annex_iii_exception_rationale text,add column if not exists annex_iii_exception_evidence_id uuid references gov_repo.evidence(evidence_id),add column if not exists prohibited_use_analysis text,add column if not exists cg_sys_001_registered boolean not null default false,add column if not exists cg_sys_002_owner boolean not null default false,add column if not exists cg_sys_003_risk_classified boolean not null default false,add column if not exists cg_sys_004_tech_doc boolean not null default false,add column if not exists cg_sys_005_risk_mgmt boolean not null default false,add column if not exists cg_sys_006_human_oversight boolean not null default false,add column if not exists cg_sys_007_conformity boolean not null default false,add column if not exists cg_sys_008_post_market boolean not null default false;;
